<?php
$st = new SplStack; $st->push(1); $st->push(2); $st->push(3); echo $st->pop(), $st->top(), count($st), "\n"; foreach ($st as $v) echo $v; echo "\n";
$q = new SplQueue; $q->enqueue('a'); $q->enqueue('b'); echo $q->dequeue(), count($q), "\n";
$h = new SplMinHeap; foreach ([5, 1, 8, 3] as $x) $h->insert($x); echo $h->extract(), $h->top(), "\n"; foreach ($h as $v) echo $v; echo "\n";
$mh = new SplMaxHeap; foreach ([5, 1, 8, 3] as $x) $mh->insert($x); foreach ($mh as $v) echo $v; echo "\n";
$pq = new SplPriorityQueue; $pq->insert('low', 1); $pq->insert('high', 10); $pq->insert('mid', 5); echo $pq->extract(), " ", count($pq), "\n";
$fa = new SplFixedArray(3); $fa[0] = 'x'; echo $fa->getSize(), $fa[0], var_export($fa[1], true), "\n"; print_r($fa->toArray());
$os = new SplObjectStorage; $o1 = new stdClass; $os->attach($o1); $os->attach(new stdClass); echo count($os), $os->contains($o1) ? 'Y' : 'N', "\n";
$ao = new ArrayObject(['b' => 2, 'a' => 1]); $ao->ksort(); print_r($ao->getArrayCopy()); foreach ($ao as $k => $v) echo "$k$v"; echo "\n";
$it = new ArrayIterator([1, 2, 3, 4, 5]); $f = new CallbackFilterIterator($it, fn($v) => $v % 2 == 1); echo implode(',', iterator_to_array($f, false)), "\n";
$lim = new LimitIterator(new ArrayIterator(range(1, 10)), 2, 3); echo implode(',', iterator_to_array($lim, false)), "\n";
$rii = new RecursiveIteratorIterator(new RecursiveArrayIterator([1, [2, [3, 4]], 5])); echo implode(',', iterator_to_array($rii, false)), "\n";
$ai = new AppendIterator; $ai->append(new ArrayIterator([1, 2])); $ai->append(new ArrayIterator([3])); echo implode(',', iterator_to_array($ai, false)), "\n";
$gen = (function() { yield 1; yield 2; })(); echo implode(',', iterator_to_array(new IteratorIterator($gen))), "\n";
$wm = new WeakMap; $k = new stdClass; $wm[$k] = 'data'; echo $wm[$k], count($wm), "\n";
date_default_timezone_set('UTC');
$ts = 1700000000;
echo date('Y-m-d H:i:s', $ts), " ", date('D, d M Y', $ts), " ", date('N jS F y, g:i a', $ts), " ", date('L t W z', $ts), "\n";
echo date('c', $ts), " ", date('r', $ts), " ", date('U', $ts), " ", date('\T\o\d\a\y \i\s l', $ts), "\n";
echo mktime(12, 0, 0, 6, 15, 2023), " ", gmmktime(0, 0, 0, 1, 1, 2000), " ", checkdate(2, 29, 2024) ? 'leap' : '', checkdate(2, 29, 2023) ? 'x' : 'noleap', "\n";
echo strtotime('2024-01-15'), " ", strtotime('2024-01-15 10:30:00'), " ", date('Y-m-d', strtotime('+1 day', $ts)), " ", date('Y-m-d', strtotime('+1 month', $ts)), " ", date('Y-m-d', strtotime('next monday', $ts)), "\n";
echo date('Y-m-d', strtotime('last day of next month', $ts)), " ", date('Y-m-d', strtotime('first day of this month', $ts)), " ", date('Y-m-d H:i', strtotime('tomorrow', $ts)), " ", date('Y-m-d', strtotime('-2 weeks', $ts)), "\n";
echo date('Y-m-d', strtotime('15 March 2024')), " ", date('Y-m-d', strtotime('March 15, 2024')), " ", date('Y-m-d', strtotime('2024/03/15')), " ", date('Y-m-d', strtotime('03/15/2024')), " ", var_export(strtotime('not a date'), true), "\n";
$d = new DateTime('2024-02-28 10:00:00'); $d->modify('+1 day'); echo $d->format('Y-m-d l'), "\n";
$d2 = new DateTimeImmutable('2024-01-31'); $d3 = $d2->add(new DateInterval('P1M')); echo $d2->format('Y-m-d'), " ", $d3->format('Y-m-d'), "\n";
$a = new DateTime('2024-01-01'); $b = new DateTime('2024-03-15 12:30:00'); $diff = $a->diff($b); echo $diff->days, " ", $diff->m, " ", $diff->d, " ", $diff->h, " ", $diff->format('%a days, %h hours, %R'), "\n";
$dt = DateTime::createFromFormat('d/m/Y H:i', '25/12/2024 18:30'); echo $dt->format('Y-m-d H:i'), "\n";
echo (new DateTime('@86400'))->format('Y-m-d'), " ", (new DateTime('2024-06-01', new DateTimeZone('America/New_York')))->format('Y-m-d H:i T P'), "\n";
date_default_timezone_set('Europe/Paris'); echo date('Y-m-d H:i T', 1700000000), " ", date('I', 1690000000), " ", date_default_timezone_get(), "\n";
$p = new DatePeriod(new DateTime('2024-01-01'), new DateInterval('P1D'), new DateTime('2024-01-04')); foreach ($p as $day) echo $day->format('md '), ''; echo "\n";
echo (new DateTime('2024-01-01'))->format(DateTime::ATOM), " ", DATE_RFC2822, "\n";
var_dump((new DateTime('2024-01-01')) < (new DateTime('2024-01-02')));
